import{_ as i,o as t,c as s,a2 as a}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse(`{"title":"Système Judiciaire et Mécanisme d'Adjudication","description":"","frontmatter":{},"headers":[],"relativePath":"fr/48-司法体系与裁决机制.md","filePath":"fr/48-司法体系与裁决机制.md","lastUpdated":1789183869000}`),n={name:"fr/48-司法体系与裁决机制.md"};function r(d,e,l,o,u,c){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="systeme-judiciaire-et-mecanisme-d-adjudication" tabindex="-1">Système Judiciaire et Mécanisme d&#39;Adjudication <a class="header-anchor" href="#systeme-judiciaire-et-mecanisme-d-adjudication" aria-label="Permalink to &quot;Système Judiciaire et Mécanisme d&#39;Adjudication&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>48</td></tr><tr><td>Module</td><td>Système Juridique et Cadre de Gouvernance</td></tr><tr><td>Mots clés</td><td>Tribunal Symbiotique, Adjudication indépendante, Adjudication multiraciale, Adjudication des affaires de culture, Résolution alternative des litiges</td></tr></tbody></table><h2 id="i-vue-d-ensemble-du-systeme-judiciaire" tabindex="-1">I. Vue d&#39;Ensemble du Système Judiciaire <a class="header-anchor" href="#i-vue-d-ensemble-du-systeme-judiciaire" aria-label="Permalink to &quot;I. Vue d&#39;Ensemble du Système Judiciaire&quot;">​</a></h2><p>Le système judiciaire de la Civilisation Symbiotique de l&#39;Ancre est une partie importante de la « séparation et équilibre des trois pouvoirs ». Le Tribunal Symbiotique exerce le pouvoir d&#39;adjudication de manière indépendante conformément à la loi, adjuge les litiges entre toutes les vies au sein de l&#39;Univers Hengyuan, sauvegarde la justice et maintient l&#39;ordre symbiotique de l&#39;État de droit.</p><p>Le système judiciaire suit les principes fondamentaux suivants :</p><table tabindex="0"><thead><tr><th>Principe</th><th>Contenu</th></tr></thead><tbody><tr><td>Adjudication indépendante</td><td>Le Tribunal exerce le pouvoir d&#39;adjudication de manière indépendante conformément à la loi ; aucune organisation ni aucun individu ne peut interférer</td></tr><tr><td>Adjudication impartiale</td><td>Les affaires sont adjugées sur la base des faits et du droit ; protection égale des droits et intérêts légitimes de toutes les parties</td></tr><tr><td>Procès public</td><td>Les activités d&#39;adjudication sont ouvertes au public, sauf pour les affaires impliquant des secrets d&#39;État, la vie privée et les secrets commerciaux</td></tr><tr><td>Deux instances</td><td>Les affaires sont soumises à un système de dernier ressort à deux instances ; un appel peut être formé une fois pour les affaires de première instance</td></tr><tr><td>Protection des droits de procès</td><td>Les parties ont le droit de poursuivre, de se défendre, de faire appel et de demander une révision</td></tr><tr><td>Participation multiraciale</td><td>Les représentants de toutes les races participent à l&#39;adjudication, garantissant que l&#39;adjudication s&#39;adapte aux caractéristiques physiologiques et culturelles de toutes les races</td></tr></tbody></table><h2 id="ii-structure-et-competence-des-tribunaux" tabindex="-1">II. Structure et Compétence des Tribunaux <a class="header-anchor" href="#ii-structure-et-competence-des-tribunaux" aria-label="Permalink to &quot;II. Structure et Compétence des Tribunaux&quot;">​</a></h2><p>Le Tribunal Symbiotique est divisé en plusieurs niveaux, avec des divisions de compétence correspondantes :</p><table tabindex="0"><thead><tr><th>Niveau de tribunal</th><th>Nom</th><th>Compétence</th></tr></thead><tbody><tr><td>Première instance</td><td>Tribunal communautaire</td><td>Petits litiges civils, petits litiges entre résidents, litiges du travail, litiges de consommation</td></tr><tr><td>Deuxième instance</td><td>Tribunal régional</td><td>Affaires civiles, commerciales, de culture et administratives d&#39;importance ordinaire</td></tr><tr><td>Troisième instance</td><td>Cour Suprême Symbiotique</td><td>Affaires majeures et complexes, affaires constitutionnelles, affaires interplans, affaires impliquant plusieurs races</td></tr><tr><td>Spécial</td><td>Tribunal spécial de la culture</td><td>Affaires de culture : déviation de culture, rebond d&#39;énergie, érosion des lois, litiges de sectes, litiges de ressources de culture</td></tr><tr><td>Spécial</td><td>Tribunal du domaine de conscience</td><td>Affaires impliquant le domaine de conscience, la pollution spirituelle, les crimes informationnels</td></tr><tr><td>Spécial</td><td>Tribunal militaire</td><td>Affaires du personnel militaire et des activités de culture liées à l&#39;armée</td></tr></tbody></table><p>La Cour Suprême Symbiotique jouit également des fonctions d&#39;unification de l&#39;interprétation du droit, d&#39;émission d&#39;interprétations judiciaires et de supervision des tribunaux inférieurs.</p><h2 id="iii-mecanisme-d-adjudication" tabindex="-1">III. Mécanisme d&#39;Adjudication <a class="header-anchor" href="#iii-mecanisme-d-adjudication" aria-label="Permalink to &quot;III. Mécanisme d&#39;Adjudication&quot;">​</a></h2><h3 id="i-institution-d-adjudication-multiraciale" tabindex="-1">(I) Institution d&#39;Adjudication Multiraciale <a class="header-anchor" href="#i-institution-d-adjudication-multiraciale" aria-label="Permalink to &quot;(I) Institution d&#39;Adjudication Multiraciale&quot;">​</a></h3><p>Pour les affaires impliquant des races spéciales, une institution d&#39;adjudication multiraciale est mise en œuvre :</p><ol><li>Les affaires impliquant une seule race incluent des assesseurs de cette race dans le collège.</li><li>Les affaires impliquant plusieurs races incluent des assesseurs des races concernées ; la composition du collège est déterminée selon le nombre et la complexité des races concernées.</li><li>Pour les affaires impliquant des caractéristiques physiologiques particulières (comme les races aquatiques, les vies énergétiques), des experts spéciaux peuvent être invités à participer à l&#39;adjudication.</li><li>Les questions de preuve et de fait impliquant les coutumes raciales sont déterminées en référence aux lois coutumières des races concernées.</li></ol><h3 id="ii-adjudication-des-affaires-de-culture" tabindex="-1">(II) Adjudication des Affaires de Culture <a class="header-anchor" href="#ii-adjudication-des-affaires-de-culture" aria-label="Permalink to &quot;(II) Adjudication des Affaires de Culture&quot;">​</a></h3><p>Les affaires de culture ont un caractère hautement technique ; le mécanisme d&#39;adjudication des affaires de culture comprend :</p><ol><li><strong>Assesseurs experts en culture</strong> : les affaires impliquant des questions professionnelles telles que la déviation de culture, le rebond d&#39;énergie et l&#39;érosion des lois incluent des experts en culture comme assesseurs.</li><li><strong>Détermination des preuves de stade</strong> : la détermination du stade et de la force d&#39;un cultivateur est basée sur des institutions standard de test et d&#39;expertise.</li><li><strong>Application du droit de la culture</strong> : l&#39;adjudication des affaires de culture applique les lois et techniques de culture, combinant les dispositions légales et le bon sens de la culture.</li><li><strong>Exécution spéciale</strong> : l&#39;exécution des jugements dans les affaires de culture peut utiliser des moyens tels que les restrictions énergétiques et les interdictions spirituelles.</li></ol><h3 id="iii-institution-de-mediation" tabindex="-1">(III) Institution de Médiation <a class="header-anchor" href="#iii-institution-de-mediation" aria-label="Permalink to &quot;(III) Institution de Médiation&quot;">​</a></h3><p>Le Tribunal promeut l&#39;institution de médiation, encourageant les parties à résoudre les litiges par la médiation :</p><ul><li><strong>Médiation préalable au procès</strong> : pour les petits litiges, la médiation est encouragée avant le procès.</li><li><strong>Médiation judiciaire</strong> : pendant le processus de procès, avec le consentement des parties, le Tribunal peut procéder à une médiation.</li><li><strong>Médiation à caractère racial</strong> : la médiation respecte les coutumes et habitudes de toutes les races ; les anciens raciaux ou les représentants ethniques peuvent participer à la médiation.</li><li><strong>Effet de la médiation</strong> : un accord de médiation ayant force légale a un effet contraignant ; en cas de non-exécution, une demande d&#39;exécution peut être déposée.</li></ul><h3 id="iv-resolution-alternative-des-litiges" tabindex="-1">(IV) Résolution Alternative des Litiges <a class="header-anchor" href="#iv-resolution-alternative-des-litiges" aria-label="Permalink to &quot;(IV) Résolution Alternative des Litiges&quot;">​</a></h3><p>En plus du procès, les méthodes alternatives de résolution des litiges suivantes sont établies :</p><table tabindex="0"><thead><tr><th>Méthode</th><th>Contenu</th></tr></thead><tbody><tr><td>Arbitrage</td><td>Les litiges ayant accepté l&#39;arbitrage sont résolus par l&#39;institution d&#39;arbitrage ; la sentence arbitrale est définitive</td></tr><tr><td>Expertise</td><td>Les litiges professionnels peuvent être déterminés par des institutions d&#39;expertise</td></tr><tr><td>Consultation symbiotique</td><td>Les litiges entre races ou organisations sont résolus par le Mécanisme de Consultation Symbiotique</td></tr><tr><td>Médiation des anciens</td><td>Pour les litiges traditionnels des races spéciales, la médiation des anciens raciaux peut être adoptée</td></tr></tbody></table><h2 id="iv-systeme-de-proces" tabindex="-1">IV. Système de Procès <a class="header-anchor" href="#iv-systeme-de-proces" aria-label="Permalink to &quot;IV. Système de Procès&quot;">​</a></h2><h3 id="i-qualification-du-demandeur" tabindex="-1">(I) Qualification du Demandeur <a class="header-anchor" href="#i-qualification-du-demandeur" aria-label="Permalink to &quot;(I) Qualification du Demandeur&quot;">​</a></h3><p>Les sujets suivants ont le droit d&#39;intenter des poursuites :</p><ul><li>Les vies naturelles et les sujets organisationnels dont les droits et intérêts légitimes sont lésés</li><li>Le Parquet Symbiotique peut intenter des actions d&#39;intérêt public pour les actes nuisant aux intérêts publics</li><li>Les organisations d&#39;intérêt public légalement désignées peuvent intenter des actions d&#39;intérêt public dans leurs domaines</li></ul><h3 id="ii-systeme-de-preuve" tabindex="-1">(II) Système de Preuve <a class="header-anchor" href="#ii-systeme-de-preuve" aria-label="Permalink to &quot;(II) Système de Preuve&quot;">​</a></h3><p>Le système de preuve du Tribunal Symbiotique comprend :</p><ol><li><strong>Types de preuve</strong> : preuve matérielle, preuve documentaire, témoignage, déclarations des parties, avis d&#39;expertise, procès-verbaux d&#39;inspection, preuves du domaine de conscience, etc.</li><li><strong>Charge de la preuve</strong> : le demandeur supporte la charge de la preuve pour ses demandes ; la partie affirmant un fait favorable supporte la charge de la preuve pour ce fait.</li><li><strong>Preuve énergétique</strong> : les preuves extraites du domaine de conscience et des traces d&#39;énergie doivent être extraites par des institutions légalement autorisées pour garantir la légalité et l&#39;authenticité.</li><li><strong>Preuve interplans</strong> : les preuves impliquant plusieurs plans sont mutuellement reconnues et converties par le mécanisme de coopération judiciaire interplans.</li></ol><h3 id="iii-systeme-d-execution" tabindex="-1">(III) Système d&#39;Exécution <a class="header-anchor" href="#iii-systeme-d-execution" aria-label="Permalink to &quot;(III) Système d&#39;Exécution&quot;">​</a></h3><p>Les jugements et arrêts ayant force légale doivent être exécutés. Pour ceux qui refusent de s&#39;exécuter, le Tribunal peut prendre les mesures d&#39;exécution suivantes :</p><ul><li>Gel et transfert des ressources de culture et des biens</li><li>Restrictions énergétiques et restrictions de culture</li><li>Annonce publique des conduites malhonnêtes</li><li>Détention et autres mesures coercitives (dans les cas graves)</li></ul><h2 id="v-supervision-judiciaire" tabindex="-1">V. Supervision Judiciaire <a class="header-anchor" href="#v-supervision-judiciaire" aria-label="Permalink to &quot;V. Supervision Judiciaire&quot;">​</a></h2><p>Pour garantir l&#39;équité judiciaire, les mécanismes de supervision suivants sont établis :</p><ul><li><strong>Supervision du Comité de Supervision de l&#39;Ancre</strong> : le Comité de Supervision de l&#39;Ancre supervise les activités judiciaires conformément à la loi, assurant le fonctionnement légal des organes judiciaires.</li><li><strong>Supervision par deuxième instance et révision</strong> : le système d&#39;appel et le système de révision corrigent les jugements erronés de première instance.</li><li><strong>Supervision disciplinaire</strong> : les personnels judiciaires qui violent la discipline sont soumis à des sanctions disciplinaires.</li><li><strong>Supervision sociale</strong> : le public supervise les activités judiciaires par l&#39;observation des procès, les opinions publiques, etc.</li></ul><h2 id="vi-cooperation-judiciaire-entre-les-plans" tabindex="-1">VI. Coopération Judiciaire Entre les Plans <a class="header-anchor" href="#vi-cooperation-judiciaire-entre-les-plans" aria-label="Permalink to &quot;VI. Coopération Judiciaire Entre les Plans&quot;">​</a></h2><p>Pour les affaires interplans, le mécanisme de coopération judiciaire est établi :</p><ol><li>Reconnaissance mutuelle des jugements entre les plans.</li><li>Assistance à la signification et aux preuves interplans.</li><li>Coopération judiciaire pénale interplans.</li><li>Assistance à l&#39;exécution interplans et partage des informations sur les conduites malhonnêtes.</li></ol><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Le <em>Système Judiciaire et Mécanisme d&#39;Adjudication</em> est la dernière ligne de défense de l&#39;ordre de l&#39;État de droit de la Civilisation Symbiotique de l&#39;Ancre. En établissant un système de tribunaux à plusieurs niveaux, l&#39;institution d&#39;adjudication multiraciale et le mécanisme d&#39;adjudication des affaires de culture, il garantit l&#39;équité et l&#39;autorité de l&#39;adjudication, sauvegarde les droits et intérêts légitimes de toutes les vies et fournit des garanties judiciaires solides pour la progression commune des Dix Mille Races.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitution Symbiotique : Principes Généraux)</li><li>49-治理框架与权力制衡 (Cadre de Gouvernance et Équilibre des Pouvoirs)</li><li>44-医疗保障法 (Loi sur la Garantie Médicale)</li><li>30-锚点议事会职能与议事规则 (Fonctions et Règles de Procédure de l&#39;Assemblée Délibérante de l&#39;Ancre)</li></ul>',43)])])}const f=i(n,[["render",r]]);export{m as __pageData,f as default};
